window.SAOMD_STORIES[410400101]={"id":410400101,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410400101:1:1","speaker":"Yui","text":"Mommy, Daddy! Good morning.","pose":20090205,"background":"bg_11_home_lounge","item":"","illustration":"","speaker_zh":"结衣","text_zh":"妈妈，爸爸！早上好。"},{"uid":"410400101:1:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:1:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410400101:2:1","speaker":"Kirito","text":"Mornin', Yui.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"早啊，结衣。"}]},{"id":3,"order":3,"actions":[{"uid":"410400101:3:1","speaker":"Asuna","text":"Good morning, Yui!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"结衣早上好！"}]},{"id":4,"order":4,"actions":[{"uid":"410400101:4:1","speaker":"Asuna","text":"Oh, Yui, could you display\ntoday's MMO Tomorrow\nfor me?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦，结衣，你能帮我展示一下今天的MMO明天吗？"}]},{"id":5,"order":5,"actions":[{"uid":"410400101:5:1","speaker":"Yui","text":"Sure!","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"当然！"}]},{"id":6,"order":6,"actions":[{"uid":"410400101:6:1","speaker":"Yui","text":"...","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"..."}]},{"id":7,"order":7,"actions":[{"uid":"410400101:7:1","speaker":"Yui","text":"Download complete.\nHere you go, Daddy.","pose":20090204,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"下载完成。给你，爸爸。"}]},{"id":8,"order":8,"actions":[{"uid":"410400101:8:1","speaker":"Kirito","text":"Thanks, Yui.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"谢谢结衣。"}]},{"id":9,"order":9,"actions":[{"uid":"410400101:9:1","speaker":"Kirito","text":"Now then, what's today's\nfront-page story...?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那么，今天的头版报道是什么呢……？"}]},{"id":10,"order":10,"actions":[{"uid":"410400101:10:1","speaker":"Asuna","text":"Come on, you two!\nBreakfast is ready.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你们两个加油！早餐准备好了。"}]},{"id":11,"order":11,"actions":[{"uid":"410400101:11:1","speaker":"Kirito","text":"Uh-huh, cool, cool...\nThanks, Asuna.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯嗯，酷，酷……谢谢，亚丝娜。"}]},{"id":12,"order":12,"actions":[{"uid":"410400101:12:1","speaker":"Asuna","text":"Kirito, manners! Put the newspaper\naway at the breakfast table.\nIt's rude!","pose":10020910,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人，有礼了！把报纸放在早餐桌上。这太粗鲁了！"},{"uid":"410400101:12:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":13,"order":13,"actions":[{"uid":"410400101:13:1","speaker":"Kirito","text":"S-Sorry...\nWait... What?!","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对、对不起……等等……什么？！"}]},{"id":14,"order":14,"actions":[{"uid":"410400101:14:1","speaker":"Asuna","text":"Kirito? What is it?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人？它是什么？"}]},{"id":15,"order":15,"actions":[{"uid":"410400101:15:1","speaker":"Kirito","text":"It's an article about Jotunheimr,\nbut...this looks like some\nseriously big news!","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是一篇关于幽兹海姆的文章，但是……这看起来像是一个重大新闻！"}]},{"id":16,"order":16,"actions":[{"uid":"410400101:16:1","speaker":"Asuna","text":"Big news?","pose":100209032,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"大新闻？"}]},{"id":17,"order":17,"actions":[{"uid":"410400101:17:1","speaker":"Kirito","text":"Remember how the enemies there\nare so much stronger than the\nones here on the surface?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"还记得那里的敌人比地表强这么多吗？"}]},{"id":18,"order":18,"actions":[{"uid":"410400101:18:1","speaker":"Asuna","text":"Yeah. It's so intense that you're\nsure to be wiped out soon unless\nyou go with an advanced party.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯。它是如此激烈，除非你和先进的队伍一起去，否则你很快就会被消灭。"}]},{"id":19,"order":19,"actions":[{"uid":"410400101:19:1","speaker":"Kirito","text":"There's even a new crazy\nhack-and-slash quest\nthere for masochists.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"甚至还有针对受虐狂的新的疯狂砍杀任务。"}]},{"id":20,"order":20,"actions":[{"uid":"410400101:20:1","speaker":"Asuna","text":"Hack-and-slash for masochists?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"受虐狂砍杀？"}]},{"id":21,"order":21,"actions":[{"uid":"410400101:21:1","speaker":"Kirito","text":"Yeah, since it's mainly\nthe players getting\nhacked and slashed...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊，主要是玩家被黑了……"}]},{"id":22,"order":22,"actions":[{"uid":"410400101:22:1","speaker":"Asuna","text":"Ha ha! Now I see\nwhat you mean.","pose":100209032,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哈哈！现在我明白你的意思了。"}]},{"id":23,"order":23,"actions":[{"uid":"410400101:23:1","speaker":"Yui","text":"Yeah! Daddy tried that quest\non his own and nearly died!","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"是啊！爸爸独自尝试了这个任务，差点就死了！"}]},{"id":24,"order":24,"actions":[{"uid":"410400101:24:1","speaker":"Asuna","text":"Y-You did what?!","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你、你做了什么？！"}]},{"id":25,"order":25,"actions":[{"uid":"410400101:25:1","speaker":"Kirito","text":"H-Hey, Yui! Didn't we agree not\nto tell Mommy about that...?","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"喂、喂，结衣！我们不是说好了不告诉妈妈这件事吗……？"}]},{"id":26,"order":26,"actions":[{"uid":"410400101:26:1","speaker":"Yui","text":"Oh, yeah...\nI'm sorry, Daddy.","pose":200902022,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"噢，是的……对不起，爸爸。"}]},{"id":27,"order":27,"actions":[{"uid":"410400101:27:1","speaker":"Asuna","text":"Agh, Kirito! Why are you always\nputting yourself in danger\nlike that?","pose":10020910,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哎呀，桐人！为什么你总是把自己置于这样的危险之中？"}]},{"id":28,"order":28,"actions":[{"uid":"410400101:28:1","speaker":"Kirito","text":"Ha ha! I was just interested in\nseeing how tough it really was.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈！我只是想看看这到底有多艰难。"}]},{"id":29,"order":29,"actions":[{"uid":"410400101:29:1","speaker":"Kirito","text":"And I did make it out in one\npiece... But it says somebody\nbeat the whole quest alone!","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"而且我确实是一气呵成的……不过据说有人独自完成了整个任务！"}]},{"id":30,"order":30,"actions":[{"uid":"410400101:30:1","speaker":"Asuna","text":"Huh?","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"咦？"}]},{"id":31,"order":31,"actions":[{"uid":"410400101:31:1","speaker":"Kirito","text":"Imagine taking on a fight\nlike that all by yourself-","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"想象一下一个人进行这样的战斗吧——"}]},{"id":32,"order":32,"actions":[{"uid":"410400101:32:1","speaker":"Yui","text":"You're one to talk, Daddy...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"你是一个会说话的人，爸爸……"}]},{"id":33,"order":33,"actions":[{"uid":"410400101:33:1","speaker":"Kirito","text":"But someone actually made it all\nthe way! Whoever they are, they've\ngot to be pretty incredible.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是居然有人成功了！无论他们是谁，他们都必须非常不可思议。"}]},{"id":34,"order":34,"actions":[{"uid":"410400101:34:1","speaker":"Asuna","text":"Does the article mention\nthat player's avatar name?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"文章里有提到玩家的虚拟形象名字吗？"}]},{"id":35,"order":35,"actions":[{"uid":"410400101:35:1","speaker":"Kirito","text":"No... It looks like they don't\nknow it yet. All they have to go\non so far are a few pictures.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不……看来他们还不知道。到目前为止，他们所要做的只是几张照片。"}]},{"id":36,"order":36,"actions":[{"uid":"410400101:36:1","speaker":"Asuna","text":"I see...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我明白了……"}]},{"id":37,"order":37,"actions":[{"uid":"410400101:37:1","speaker":"Kirito","text":"I've got to figure out who it is!\nI'm going to look into this...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我得弄清楚是谁！我要调查一下这个..."},{"uid":"410400101:37:2","speaker":"Yui","text":"","pose":200902022,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410400101:38:1","speaker":"Leafa","text":"And here we are!","pose":10030104,"background":"bg_event_urtharbrunnr","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我们到了！"},{"uid":"410400101:38:2","speaker":"Sinon","text":"","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":39,"order":39,"actions":[{"uid":"410400101:39:1","speaker":"Sinon","text":"It's been ages since I was\nlast in Jotunheimr.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"距离上次来幽兹海姆已经过去很多年了。"}]},{"id":40,"order":40,"actions":[{"uid":"410400101:40:1","speaker":"Kirito","text":"You two will be a real\nbig help today!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你们两个今天真是帮大忙了！"},{"uid":"410400101:40:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:40:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":41,"order":41,"actions":[{"uid":"410400101:41:1","speaker":"Asuna","text":"It's good to see you, Leafa!\nYou too, Sinonon!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"很高兴见到你，莉法！你也是，诗乃！"},{"uid":"410400101:41:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410400101:42:1","speaker":"Leafa","text":"So you're trying to find the\nmad genius who beat that\nnightmare-quest?","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"所以你想找到那个完成噩梦任务的疯狂天才？"},{"uid":"410400101:42:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":43,"order":43,"actions":[{"uid":"410400101:43:1","speaker":"Asuna","text":"That's the plan.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"计划是这样的。"},{"uid":"410400101:43:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:43:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410400101:44:1","speaker":"Sinon","text":"It sure is odd. Think of the\nplayers who usually clear\ndeath-quests like this.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"确实很奇怪。想想通常这样完成死亡任务的玩家。"},{"uid":"410400101:44:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410400101:45:1","speaker":"Sinon","text":"You'd think they wouldn't stop\nbragging about it. Soon enough,\neveryone would know.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"你会认为他们不会停止吹牛。很快，每个人都会知道。"}]},{"id":46,"order":46,"actions":[{"uid":"410400101:46:1","speaker":"Sinon","text":"But so far, nobody's taken credit.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"但到目前为止，还没有人把功劳揽在自己身上。"}]},{"id":47,"order":47,"actions":[{"uid":"410400101:47:1","speaker":"Kirito","text":"That's what you'd expect from\nmost players. But maybe...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这就是你对大多数玩家的期望。但也许..."},{"uid":"410400101:47:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:47:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":48,"order":48,"actions":[{"uid":"410400101:48:1","speaker":"Kirito","text":"Maybe it's not a player\nwe're dealing with.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许我们面对的不是玩家。"}]},{"id":49,"order":49,"actions":[{"uid":"410400101:49:1","speaker":"Asuna","text":"Huh? You mean an NPC?","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯？你的意思是NPC？"},{"uid":"410400101:49:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":50,"order":50,"actions":[{"uid":"410400101:50:1","speaker":"Leafa","text":"So the NPC beating the quest was\npart of the storyline? Well,\nI guess that's possible...","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"所以NPC完成任务是故事情节的一部分？嗯，我想这是可能的......"},{"uid":"410400101:50:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":51,"order":51,"actions":[{"uid":"410400101:51:1","speaker":"Sinon","text":"But that means there's a connection\nbetween players who've taken on the\nquest and that NPC, right?","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"但是这意味着接受任务的玩家和那个NPC之间有联系吧？"}]},{"id":52,"order":52,"actions":[{"uid":"410400101:52:1","speaker":"Asuna","text":"That's true. There have got to\nbe players who have beaten the\nevent.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"确实如此。一定有玩家击败了该赛事。"},{"uid":"410400101:52:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:52:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":53,"order":53,"actions":[{"uid":"410400101:53:1","speaker":"Sinon","text":"But we don't even know who\nthose players could be...","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"但我们甚至不知道那些玩家可能是谁......"},{"uid":"410400101:53:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":54,"order":54,"actions":[{"uid":"410400101:54:1","speaker":"Sinon","text":"Is that even possible? Either way,\nI have a feeling they're trying to\nlet people know how to beat it.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"这可能吗？不管怎样，我有一种感觉，他们试图让人们知道如何战胜它。"}]},{"id":55,"order":55,"actions":[{"uid":"410400101:55:1","speaker":"Kirito","text":"I thought the same thing. That's\none of the things I want to get\nto the bottom of.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我也是这么想的。这是我想查清真相的事情之一。"},{"uid":"410400101:55:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:55:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":56,"order":56,"actions":[{"uid":"410400101:56:1","speaker":"Asuna","text":"You know where the\nquest area is, right?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你知道任务区在哪里吧？"}]},{"id":57,"order":57,"actions":[{"uid":"410400101:57:1","speaker":"Yui","text":"Yes. It's just beyond this wasteland.\nBut you need to take out a monster\nvanguard to get there.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"是的。就在这片荒地之外。但你需要干掉怪物先锋才能到达那里。"}]},{"id":58,"order":58,"actions":[{"uid":"410400101:58:1","speaker":"Yui","text":"I think the person we're\nlooking for could still\nbe around here.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我想我们要找的人可能还在这附近。"}]},{"id":59,"order":59,"actions":[{"uid":"410400101:59:1","speaker":"Leafa","text":"Thanks, Yui.","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"谢谢结衣。"},{"uid":"410400101:59:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":60,"order":60,"actions":[{"uid":"410400101:60:1","speaker":"Kirito","text":"Alright, guys!\nLet's do this!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好了，各位！让我们这样做吧！"},{"uid":"410400101:60:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:60:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410400101:61:1","speaker":"Asuna","text":"Yeah!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯！"},{"uid":"410400101:61:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":62,"order":62,"actions":[{"uid":"410400101:62:1","speaker":"Leafa","text":"Ugh...\nI'm so exhausted...","pose":10030102,"background":"bg_08_forest","item":"","illustration":"","speaker_zh":"莉法","text_zh":"呃……我好累……"},{"uid":"410400101:62:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":63,"order":63,"actions":[{"uid":"410400101:63:1","speaker":"Sinon","text":"Leafa... This is a VRMMO.\nYou can't get exhausted...","pose":100402042,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"莉法...这是VRMMO。你不能累死..."}]},{"id":64,"order":64,"actions":[{"uid":"410400101:64:1","speaker":"Asuna","text":"Hahaha! You say that, Sinonon,\nbut you're looking pretty worn\nout yourself...","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哈哈哈！诗乃虽然这么说，但你看起来也很疲惫啊……"},{"uid":"410400101:64:2","speaker":"Kirito","text":"","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:64:3","speaker":"Yui","text":"","pose":200902032,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410400101:65:1","speaker":"Sinon","text":"I'm just psychologically run down\nfrom that battle...","pose":10040203,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我只是因为那场战斗而精神崩溃了……"},{"uid":"410400101:65:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":66,"order":66,"actions":[{"uid":"410400101:66:1","speaker":"Kirito","text":"Ha ha! Well, if you\nput it that way...","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈！好吧，如果你这样说的话......"},{"uid":"410400101:66:2","speaker":"Yui","text":"","pose":200902032,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400101:66:3","speaker":"Asuna","text":"","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":67,"order":67,"actions":[{"uid":"410400101:67:1","speaker":"Yui","text":"I hate to bring bad news, but\nthat was only a tiny fraction\nof the enemy army...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我讨厌带来坏消息，但这只是敌军的一小部分……"}]},{"id":68,"order":68,"actions":[{"uid":"410400101:68:1","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410400101:68:2","speaker":"Leafa","text":"Huh?!\nNo way!!","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"啊？！决不！！"}]},{"id":69,"order":69,"actions":[{"uid":"410400101:69:1","speaker":"Asuna","text":"Yes way... It's a good thing we\nwere able to get out of that\nwasteland, though.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊……不过，我们能够离开那片荒地也是一件好事。"},{"uid":"410400101:69:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:69:3","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410400101:70:1","speaker":"Sinon","text":"Yeah. It's not so much that we\ndefeated the enemy but more that we\nsaw an opening and bravely ran away.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"是的。与其说我们打败了敌人，不如说我们看到了破绽，勇敢地逃跑了。"},{"uid":"410400101:70:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410400101:71:1","speaker":"Asuna","text":"Whoever was strong enough to\ntake them all down must be\nincredible.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谁强大到能把他们全部打倒，一定很了不起。"},{"uid":"410400101:71:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:71:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":72,"order":72,"actions":[{"uid":"410400101:72:1","speaker":"Kirito","text":"I'll say. And they must be\nsomewhere in these woods...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我就说吧。他们一定就在这树林里的某个地方......"},{"uid":"410400101:72:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":73,"order":73,"actions":[{"uid":"410400101:73:1","speaker":"Sinon","text":"Hey, look! There's smoke rising\nfrom that direction. There's got\nto be someone there, right?","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"嘿，看！有烟雾从那个方向升起。那里一定有人，对吗？"},{"uid":"410400101:73:2","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":74,"order":74,"actions":[{"uid":"410400101:74:1","speaker":"Kirito","text":"You're right!\nLet's check it out.","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你说得对！我们来看看吧。"},{"uid":"410400101:74:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:74:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":75,"order":75,"actions":[{"uid":"410400101:75:1","speaker":"???","text":"...","pose":10540105,"background":"bg_11_forest_yui","item":"","illustration":"","speaker_zh":"？？？","text_zh":"..."}]},{"id":76,"order":76,"actions":[{"uid":"410400101:76:1","speaker":"???","text":"Huh...?!\nWho goes there?!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"啊……？！谁去那里？"}]},{"id":77,"order":77,"actions":[{"uid":"410400101:77:1","speaker":"Kirito","text":"Aha! There they are! So this is\nthat legendary player...\nOr, um, NPC?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊哈！他们在那里！这就是传说中的玩家...或者，嗯，NPC？"},{"uid":"410400101:77:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:77:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410400101:78:1","speaker":"Asuna","text":"It's a girl in armor...","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是铠甲少女……"},{"uid":"410400101:78:2","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":79,"order":79,"actions":[{"uid":"410400101:79:1","speaker":"Leafa","text":"Wow...\nWhat a beautiful avatar.","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"哇……好漂亮的虚拟形象啊。"},{"uid":"410400101:79:2","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":80,"order":80,"actions":[{"uid":"410400101:80:1","speaker":"???","text":"Who goes there? You don't look like\nyou're of the Forces of Darkness,\nbut... State your business!","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"谁去了？你看起来不像是黑暗势力的一员，但是……说清楚你的事！"}]},{"id":81,"order":81,"actions":[{"uid":"410400101:81:1","speaker":"Kirito","text":"Ah, we're sorry! My name is\nKirito. I'm a Spriggan.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊，对不起！我的名字是桐人。我是影精灵。"},{"uid":"410400101:81:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:81:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410400101:82:1","speaker":"Kirito","text":"And these are my friends\nAsuna, Leafa, and Sinon.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是我的朋友亚丝娜、莉法和诗乃。"},{"uid":"410400101:82:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410400101:83:1","speaker":"???","text":"...","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"..."}]},{"id":84,"order":84,"actions":[{"uid":"410400101:84:1","speaker":"Kirito","text":"Umm... Would it be all right to\nask your name as well?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……也可以问一下你的名字吗？"},{"uid":"410400101:84:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:84:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":85,"order":85,"actions":[{"uid":"410400101:85:1","speaker":"???","text":"My name...?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我的名字……？"}]},{"id":86,"order":86,"actions":[{"uid":"410400101:86:1","speaker":"???","text":"My name is Alice...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我叫爱丽丝..."}]},{"id":87,"order":87,"actions":[{"uid":"410400101:87:1","speaker":"Alice","text":"I'm an Integrity Knight.\nAlice Synthesis Thirty.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我是整合骑士。 爱丽丝合成三十。"}]},{"id":88,"order":88,"actions":[{"uid":"410400101:88:1","speaker":"Kirito","text":"Alice... Synthesis?","pose":10011502,"background":"bg_11_forest_yui","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝……合成？"},{"uid":"410400101:88:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:88:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":89,"order":89,"actions":[{"uid":"410400101:89:1","speaker":"Leafa","text":"Wow, cool! I've never seen an\navatar with a middle name in\nALO before.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"哇，酷！我以前从未在ALO中见过有中间名的虚拟形象。"},{"uid":"410400101:89:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":90,"order":90,"actions":[{"uid":"410400101:90:1","speaker":"Asuna","text":"She... She's a player...right?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"她……她是玩家……对吗？"},{"uid":"410400101:90:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:90:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410400101:91:1","speaker":"Sinon","text":"Well, we won't know unless we ask.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"好吧，除非我们问，否则我们不会知道。"},{"uid":"410400101:91:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":92,"order":92,"actions":[{"uid":"410400101:92:1","speaker":"Sinon","text":"Hey, Alice. How long have\nyou been diving?","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"嘿，爱丽丝。你潜水多久了？"},{"uid":"410400101:92:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410400101:93:1","speaker":"Alice","text":"Diving...?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"潜水……？"}]},{"id":94,"order":94,"actions":[{"uid":"410400101:94:1","speaker":"Alice","text":"What in the world are\nyou talking about?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你到底在说什么？"}]},{"id":95,"order":95,"actions":[{"uid":"410400101:95:1","speaker":"Kirito","text":"...!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"...!"},{"uid":"410400101:95:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:95:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":96,"order":96,"actions":[{"uid":"410400101:96:1","speaker":"Sinon","text":"Ah, so she's an NPC.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"啊，原来她是NPC。"},{"uid":"410400101:96:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":97,"order":97,"actions":[{"uid":"410400101:97:1","speaker":"Leafa","text":"Yeah. She doesn't have wings,\nand her design doesn't look\nquite like an ALO avatar.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"是啊。她没有翅膀，而且她的设计看起来不太像ALO 虚拟形象。"}]},{"id":98,"order":98,"actions":[{"uid":"410400101:98:1","speaker":"Asuna","text":"Seems that way...\nBy the way, Alice,\nwhere are you from?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"好像是这样……对了，爱丽丝，你是哪里人？"},{"uid":"410400101:98:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:98:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410400101:99:1","speaker":"Alice","text":"You've all been talking in some\nstrange code since I\nfirst saw you... It's suspicious.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"从我第一次见到你开始，你们就一直在用奇怪的代码说话……这很可疑。"}]},{"id":100,"order":100,"actions":[{"uid":"410400101:100:1","speaker":"Kirito","text":"...!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"...!"},{"uid":"410400101:100:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:100:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410400101:101:1","speaker":"Asuna","text":"Oh! Um, we're sorry! We're, uh...\nWe're from the surface.","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦！嗯，我们很抱歉！我们，呃...我们来自地表。"}]},{"id":102,"order":102,"actions":[{"uid":"410400101:102:1","speaker":"Asuna","text":"We heard that someone finally\ndefeated the monsters here, so we\ncame down to check it out.","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"听说终于有人打败了这里的怪物，所以我们就下来看看。"},{"uid":"410400101:102:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410400101:103:1","speaker":"Alice","text":"The surface...?\nWhat are you talking about?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"表面……？你在说什么？"}]},{"id":104,"order":104,"actions":[{"uid":"410400101:104:1","speaker":"Alice","text":"The light of the Sun God Solus\nblesses this land. Surely this\nis the surface.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"太阳神索鲁斯的光芒祝福这片土地。当然这就是表面。"}]},{"id":105,"order":105,"actions":[{"uid":"410400101:105:1","speaker":"Kirito","text":"...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410400101:105:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:105:3","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":106,"order":106,"actions":[{"uid":"410400101:106:1","speaker":"Sinon","text":"Hey, Kirito...","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"喂，桐人……"},{"uid":"410400101:106:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410400101:107:1","speaker":"Kirito","text":"R-Right... For an NPC, this\ngirl's reactions are extremely\ncomplex...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对、对……对于一个NPC来说，这个女孩的反应极其复杂……"},{"uid":"410400101:107:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:107:3","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410400101:108:1","speaker":"Kirito","text":"Then she must be a player\nafter all... Or maybe...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那她一定是玩家吧……或者说……"},{"uid":"410400101:108:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410400101:109:1","speaker":"Alice","text":"It's true that Amayori and I were\nable to fend off the forces of\nthe Dark Territory.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"确实，我和雨缘确实能够抵御暗黑界的势力。"}]},{"id":110,"order":110,"actions":[{"uid":"410400101:110:1","speaker":"Alice","text":"But as time went by, it seems they\nsimply surged forth again from\nsome other place.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但随着时间的推移，他们似乎又从别的地方涌了过来。"}]},{"id":111,"order":111,"actions":[{"uid":"410400101:111:1","speaker":"Kirito","text":"Dark Territory...?\nWhat's that?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"暗黑界……？那是什么？"},{"uid":"410400101:111:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:111:3","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410400101:112:1","speaker":"Alice","text":"...We're not getting anywhere\nwith this conversation, are we?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"……我们这次谈话没有任何进展，是吗？"}]},{"id":113,"order":113,"actions":[{"uid":"410400101:113:1","speaker":"Kirito","text":"Y-You can understand that too?","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你、你也能明白吗？"},{"uid":"410400101:113:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:113:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410400101:114:1","speaker":"Alice","text":"I hoped it wouldn't come to\nthis, but... So be it. We'll\nhave a trial by duel.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我希望不要变成这样，但是……就这样吧。我们将进行决斗审判。"}]},{"id":115,"order":115,"actions":[{"uid":"410400101:115:1","speaker":"Kirito","text":"What?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？！"},{"uid":"410400101:115:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:115:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410400101:116:1","speaker":"Alice","text":"After a single battle, I'll be\nable to tell whether you're\nminions of the Dark Territory.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"只要一战，我就能判断你是不是暗黑界的爪牙了。"}]},{"id":117,"order":117,"actions":[{"uid":"410400101:117:1","speaker":"Kirito","text":"H-Hey, wait!\nWe're not your enemies...\nI think!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"喂、喂，等等！我们不是你的敌人……我想！"},{"uid":"410400101:117:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:117:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410400101:118:1","speaker":"Alice","text":"But those pointed ears of yours...\nYou certainly look like you're\nfrom the Dark Territory.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但是你那尖尖的耳朵……看起来确实像是暗黑界的人。"}]},{"id":119,"order":119,"actions":[{"uid":"410400101:119:1","speaker":"Alice","text":"And you still haven't given me\nany reason to trust you.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"而你还没有给我任何信任你的理由。"}]},{"id":120,"order":120,"actions":[{"uid":"410400101:120:1","speaker":"Kirito","text":"Dammit... Nothing you're\nsaying makes sense!","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"可恶……你说的一点道理都没有！"},{"uid":"410400101:120:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:120:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":121,"order":121,"actions":[{"uid":"410400101:121:1","speaker":"Alice","text":"Very well... I admit defeat.","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"好吧……我认输了。"}]},{"id":122,"order":122,"actions":[{"uid":"410400101:122:1","speaker":"Alice","text":"You're not from the Dark Territory.\nA gentle spar can tell me that much\nfrom your sword style, at least.","pose":10540107,"background":"bg_11_forest_yui","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你不是暗黑界的。至少，一颗温和的晶石可以从你的剑术中告诉我这么多。"}]},{"id":123,"order":123,"actions":[{"uid":"410400101:123:1","speaker":"Kirito","text":"That was a gentle spar to you?!\nWow, no wonder you managed to\nbeat that quest by yourself...","pose":100115072,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这对你来说是温柔的切磋？！哇哦，怪不得你一个人就完成了这个任务……"},{"uid":"410400101:123:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:123:3","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":124,"order":124,"actions":[{"uid":"410400101:124:1","speaker":"Asuna","text":"S-Stop!\nAlice, stop!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"住、住手！ 爱丽丝，停下！"}]},{"id":125,"order":125,"actions":[{"uid":"410400101:125:1","speaker":"Asuna","text":"We don't want to fight you!","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们不想跟你打！"},{"uid":"410400101:125:2","speaker":"Kirito","text":"","pose":100115072,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410400101:126:1","speaker":"Alice","text":"I'm still not sure I trust you...\nBut let's put away our weapons for\nnow. I don't sense malice in you.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我还是不确定我是否相信你……不过我们先把武器收起来吧。我没感觉到你有什么恶意。"}]},{"id":127,"order":127,"actions":[{"uid":"410400101:127:1","speaker":"Asuna","text":"Th-Thanks...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谢谢、谢谢……"},{"uid":"410400101:127:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400101:127:3","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":128,"order":128,"actions":[{"uid":"410400101:128:1","speaker":"Leafa","text":"We were thinking of taking on the\nsame mon-Err, I mean, the \"Forces\nof Darkness\" that you defeated.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我们正在考虑对抗同样的怪物——呃，我是说，你打败的“黑暗势力”。"},{"uid":"410400101:128:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":129,"order":129,"actions":[{"uid":"410400101:129:1","speaker":"Leafa","text":"So... I guess that\nmakes us allies!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"所以...我想这让我们成为盟友！"},{"uid":"410400101:129:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410400101:130:1","speaker":"Alice","text":"That may be true, but...you\nsaid you do not understand\nthe words I use.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"也许是这样，但是……你说你听不懂我用的话。"}]},{"id":131,"order":131,"actions":[{"uid":"410400101:131:1","speaker":"Alice","text":"And you still look as though\nyou don't trust me.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"而且你看起来还是不信任我。"}]},{"id":132,"order":132,"actions":[{"uid":"410400101:132:1","speaker":"Yui","text":"...Daddy, if she's an NPC,\nthen she's running\non non-standard AI.","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"...爸爸，如果她是NPC，那么她运行的是非标准AI。"},{"uid":"410400101:132:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400101:132:3","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410400101:133:1","speaker":"Yui","text":"To be honest...\nShe's even more advanced than me.","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"说实话……她比我还要高级。"}]},{"id":134,"order":134,"actions":[{"uid":"410400101:134:1","speaker":"Asuna","text":"M-More advanced than Yui...?\nIs that even possible in ALO?","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"M、比结衣高级……？这在 ALO 中可能吗？"}]},{"id":135,"order":135,"actions":[{"uid":"410400101:135:1","speaker":"Yui","text":"That's all I can determine from\nour interactions so far...","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"目前为止我们的互动只能确定这些了……"}]},{"id":136,"order":136,"actions":[{"uid":"410400101:136:1","speaker":"Kirito","text":"...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."}]},{"id":137,"order":137,"actions":[{"uid":"410400101:137:1","speaker":"Kirito","text":"Hey, Alice. It's true that we\ncan't understand everything\nyou're saying...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嘿，爱丽丝。确实，我们无法理解您所说的一切......"}]},{"id":138,"order":138,"actions":[{"uid":"410400101:138:1","speaker":"Kirito","text":"So how about we start over from\nthe beginning? Can you tell us\nhow you came here?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那我们从头开始怎么样？你能告诉我们你是怎么来到这里的吗？"},{"uid":"410400101:138:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":139,"order":139,"actions":[{"uid":"410400101:139:1","speaker":"Alice","text":"...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."}]},{"id":140,"order":140,"actions":[{"uid":"410400101:140:1","speaker":"Alice","text":"Very well.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"很好。"}]},{"id":141,"order":141,"actions":[{"uid":"410400101:141:1","speaker":"Alice","text":"I am an Integrity Knight of the\nAxiom Church in Centoria.\nSworn to protect the","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我是圣托利亚中公理教会的整合骑士。宣誓保护"}]},{"id":142,"order":142,"actions":[{"uid":"410400101:142:1","speaker":"Alice","text":"Human Empire from the Dark\nTerritory, I serve under the\nHigh Priest, the Administrator.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"人界，来自黑暗领域，侍奉大祭司最高祭司。"}]},{"id":143,"order":143,"actions":[{"uid":"410400101:143:1","speaker":"Leafa","text":"You do what for the who-now?","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"你现在为谁做什么？"},{"uid":"410400101:143:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":144,"order":144,"actions":[{"uid":"410400101:144:1","speaker":"Kirito","text":"Wait, Sugu. Don't interrupt.\nLet's hear her out.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"等等，小直。不要打扰。让我们听听她的说法。"},{"uid":"410400101:144:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400101:144:3","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":145,"order":145,"actions":[{"uid":"410400101:145:1","speaker":"Leafa","text":"S-Sure...","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"对、好的……"},{"uid":"410400101:145:2","speaker":"Sinon","text":"","pose":100402022,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":146,"order":146,"actions":[{"uid":"410400101:146:1","speaker":"Alice","text":"It began like any other\nnight in Centoria.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"和圣托利亚的任何一个夜晚一样开始。"}]},{"id":147,"order":147,"actions":[{"uid":"410400101:147:1","speaker":"Alice","text":"I was riding my dragon Amayori,\npatrolling the skies above the\nCentral Cathedral.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我骑着龙雨缘，在中央圣堂的上空巡逻。"}]},{"id":148,"order":148,"actions":[{"uid":"410400101:148:1","speaker":"Alice","text":"Then I saw an unmistakable\nsilhouette against the moonlight:\na Dark Knight riding dragon-back.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"然后我在月光下看到了一个明显的剪影：一个骑在龙背上的黑暗骑士。"}]},{"id":149,"order":149,"actions":[{"uid":"410400101:149:1","speaker":"Alice","text":"No intruder had ever made it\nso far into the capital. Sensing\ndanger, I went to approach him.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"还没有入侵者能够深入到王都这么远的地方。察觉到危险，我走近他。"}]},{"id":150,"order":150,"actions":[{"uid":"410400101:150:1","speaker":"Alice","text":"But as soon as he saw me, he fled\nwell beyond the boundaries of the\nCentral Capital of Centoria.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但他一看到我，就远远地逃到了圣托利亚中都之外。"}]},{"id":151,"order":151,"actions":[{"uid":"410400101:151:1","speaker":"Alice","text":"Release Recollection!","pose":10540101,"background":"bg_event_alo_sky","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"记忆解放术！"}]},{"id":152,"order":152,"actions":[{"uid":"410400101:152:1","speaker":"Dark Knight","text":"Gwaaargh....!!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"黑暗骑士","text_zh":"吼啊啊！"}]},{"id":153,"order":153,"actions":[{"uid":"410400101:153:1","speaker":"Alice","text":"And with that, the enemy\nwas no more.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这样一来，敌人就没有了。"}]},{"id":154,"order":154,"actions":[{"uid":"410400101:154:1","speaker":"Alice","text":"Come on, Amayori.\nWe'd best get going.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"来吧，雨缘。我们最好出发了。"}]},{"id":155,"order":155,"actions":[{"uid":"410400101:155:1","speaker":"Amayori","text":"Grrroouh...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"咕咕……"}]},{"id":156,"order":156,"actions":[{"uid":"410400101:156:1","speaker":"Alice","text":"What's wrong, girl?\nAww... You must be tired\nfrom all that flying.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"怎么了，姑娘？哇...你飞了这么久一定很累了。"}]},{"id":157,"order":157,"actions":[{"uid":"410400101:157:1","speaker":"Alice","text":"Let's take a little rest\non the ground.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们在地上休息一下吧。"}]},{"id":158,"order":158,"actions":[{"uid":"410400101:158:1","speaker":"Amayori","text":"Grroou!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"咕噜！"}]},{"id":159,"order":159,"actions":[{"uid":"410400101:159:1","speaker":"Alice","text":"What...?\nWhat in the world is this?","pose":10540108,"background":"bg_event_alo_cloudysky","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"什么……？这到底是什么？"}]},{"id":160,"order":160,"actions":[{"uid":"410400101:160:1","speaker":"Alice","text":"All of a sudden, the air grew hazy.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"突然，空气变得朦胧起来。"}]},{"id":161,"order":161,"actions":[{"uid":"410400101:161:1","speaker":"Alice","text":"Amayori! Do you know\nwhich way is home?!","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"雨缘！你知道回家的路是哪条路吗？！"}]},{"id":162,"order":162,"actions":[{"uid":"410400101:162:1","speaker":"Amayori","text":"Ggruu.. Ggrouuuh!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"咕咕咕咕咕咕！"}]},{"id":163,"order":163,"actions":[{"uid":"410400101:163:1","speaker":"Alice","text":"You don't know either, huh...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你也不知道吧……"}]},{"id":164,"order":164,"actions":[{"uid":"410400101:164:1","speaker":"Alice","text":"Then we have no choice.\nWe must land.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那就没办法了。我们必须着陆。"}]},{"id":165,"order":165,"actions":[{"uid":"410400101:165:1","speaker":"Alice","text":"...","pose":10540102,"background":"bg_white","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."}]},{"id":166,"order":166,"actions":[{"uid":"410400101:166:1","speaker":"Amayori","text":"Ggrauuu...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"咕咕咕……"}]},{"id":167,"order":167,"actions":[{"uid":"410400101:167:1","speaker":"Alice","text":"Wh-What could this be?\nThis strange sensation of\nbeing bathed in light...","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这、这会是什么？这种沐浴在光芒中的奇异感觉……"}]},{"id":168,"order":168,"actions":[{"uid":"410400101:168:1","speaker":"Alice","text":"What is this...?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这是什么……？"}]},{"id":169,"order":169,"actions":[{"uid":"410400101:169:1","speaker":"Alice","text":"Where are we?!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们在哪儿？！"}]},{"id":170,"order":170,"actions":[{"uid":"410400101:170:1","speaker":"Kirito","text":"So when you followed that light,\nyou ended up in our world?","pose":10011502,"background":"bg_11_forest_yui","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以当你追随那道光的时候，你就来到了我们的世界？"},{"uid":"410400101:170:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400101:170:3","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":171,"order":171,"actions":[{"uid":"410400101:171:1","speaker":"Alice","text":"Right. So we kept walking, taking\ndown any beings that seemed like\nagents of the Dark Territory...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"对。所以我们继续前行，消灭任何看似暗黑界特工的生物……"}]},{"id":172,"order":172,"actions":[{"uid":"410400101:172:1","speaker":"Alice","text":"After a few days, I happened\nupon a god of this world.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"过了几天，我偶然遇到了这个世界的神。"}]},{"id":173,"order":173,"actions":[{"uid":"410400101:173:1","speaker":"Alice","text":"Let's rest at this spring for\na while, Amayori...","pose":10540105,"background":"bg_18_mountain","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"雨缘，在这个春天休息一下吧……"}]},{"id":174,"order":174,"actions":[{"uid":"410400101:174:1","speaker":"Amayori","text":"Grauu...!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"格劳……！"}]},{"id":175,"order":175,"actions":[{"uid":"410400101:175:1","speaker":"Urdr","text":"Who might you be?","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你可能是谁？"}]},{"id":176,"order":176,"actions":[{"uid":"410400101:176:1","speaker":"Alice","text":"Y-You're...!!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你、你是……！！"},{"uid":"410400101:176:2","speaker":"Urdr","text":"","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":""}]},{"id":177,"order":177,"actions":[{"uid":"410400101:177:1","speaker":"Alice","text":"A giant woman...!\nJust like the ones I've read\nabout in books of legends...!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"巨大的女人……！就像我在传说中读到的那样……！"}]},{"id":178,"order":178,"actions":[{"uid":"410400101:178:1","speaker":"Urdr","text":"I am Urdr, Goddess of the Spring\nand Guardian of Jotunheimr.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我是乌尔德，春天的女神，幽兹海姆的守护者。"}]},{"id":179,"order":179,"actions":[{"uid":"410400101:179:1","speaker":"Alice","text":"Jotunheimr...?\nGoddess of the Spring?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"幽兹海姆……？春天女神？"}]},{"id":180,"order":180,"actions":[{"uid":"410400101:180:1","speaker":"Urdr","text":"And what is your nature, my child?","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你的本性是什么，我的孩子？"}]},{"id":181,"order":181,"actions":[{"uid":"410400101:181:1","speaker":"Alice","text":"...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."}]},{"id":182,"order":182,"actions":[{"uid":"410400101:182:1","speaker":"Urdr","text":"Allow me to divine it, then.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"那么请允许我占卜一下。"}]},{"id":183,"order":183,"actions":[{"uid":"410400101:183:1","speaker":"Urdr","text":"I sense in your being\na powerful will to fight...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我感觉到你有强大的战斗意志……"}]},{"id":184,"order":184,"actions":[{"uid":"410400101:184:1","speaker":"Urdr","text":"I see... There's no doubt\nabout it. Surely you must\nbe a knight.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我明白了……这是毫无疑问的。毫无疑问，你一定是一名骑士。"}]},{"id":185,"order":185,"actions":[{"uid":"410400101:185:1","speaker":"Urdr","text":"As it so happens, I presently\nhave need of a knight. Might\nyou listen to my plea?","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"正巧，我现在需要一名骑士。你能听听我的恳求吗？"}]},{"id":186,"order":186,"actions":[{"uid":"410400101:186:1","speaker":"Alice","text":"I... I'm sorry. I have something\nelse that I must do. I don't\nhave time for this.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我……对不起。我还有别的事必须做。我没有时间做这个。"}]},{"id":187,"order":187,"actions":[{"uid":"410400101:187:1","speaker":"Urdr","text":"I see... What a pity. I thought\nI had finally found someone to\nfell those wicked brutes...","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"原来如此……可惜了。我以为我终于找到人来打倒那些邪恶的畜生了……"}]},{"id":188,"order":188,"actions":[{"uid":"410400101:188:1","speaker":"Alice","text":"Brutes?\nYou... You must mean the\nDark Territory, right?!","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"畜生？你……你一定是说暗黑界吧？！"}]},{"id":189,"order":189,"actions":[{"uid":"410400101:189:1","speaker":"Urdr","text":"Whatever do you mean? They are the\ncreatures from the world below\nthis one, a world called Nibelheim.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你什么意思？他们是来自这个世界以下的世界，一个叫做尼福尔海姆的世界的生物。"}]},{"id":190,"order":190,"actions":[{"uid":"410400101:190:1","speaker":"Alice","text":"Nibelheim? But a moment ago\nyou said this place was called\nJotunheimr...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尼福尔海姆？但刚才你说这个地方叫幽兹海姆……"}]},{"id":191,"order":191,"actions":[{"uid":"410400101:191:1","speaker":"Alice","text":"Gaahh! I don't understand any\nof this! Are you trying to tell\nme this is another world?","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"嘎啊！这些我都不懂！你是想告诉我这是另一个世界吗？"}]},{"id":192,"order":192,"actions":[{"uid":"410400101:192:1","speaker":"Alice","text":"Enough! How dare you try to\ndeceive an Integrity Knight!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"够了！你怎么敢试图欺骗整合骑士！"}]},{"id":193,"order":193,"actions":[{"uid":"410400101:193:1","speaker":"Urdr","text":"You are a clearly a powerful knight\nwith a noble heart and a piercing\nintellect...","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你显然是一位强大的骑士，拥有高贵的心灵和敏锐的智慧......"}]},{"id":194,"order":194,"actions":[{"uid":"410400101:194:1","speaker":"Urdr","text":"Surely, you must be able to\nappreciate the truth of what\nI say to you.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"当然，你一定能够体会到我对你说的话的真实性。"}]},{"id":195,"order":195,"actions":[{"uid":"410400101:195:1","speaker":"Alice","text":"...!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"...!"}]},{"id":196,"order":196,"actions":[{"uid":"410400101:196:1","speaker":"Amayori","text":"Ggrauuu...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"咕咕咕……"}]},{"id":197,"order":197,"actions":[{"uid":"410400101:197:1","speaker":"Alice","text":"Amayori...\nYou're right.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"雨世里……你说得对。"}]},{"id":198,"order":198,"actions":[{"uid":"410400101:198:1","speaker":"Alice","text":"The form of this \"Urdr\" woman...\nShe really does look like a\ngoddess.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个“乌尔德”女人的身材……真是女神啊。"}]},{"id":199,"order":199,"actions":[{"uid":"410400101:199:1","speaker":"Alice","text":"Perhaps she's a being on the\nsame level as the Goddess Stacia.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"或许她是和女神丝提西亚同一层次的存在吧。"}]},{"id":200,"order":200,"actions":[{"uid":"410400101:200:1","speaker":"Alice","text":"Very well...\nGoddess of this realm.\nI will hear your request.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"很好……这个境界的女神。我会听到你的请求。"}]},{"id":201,"order":201,"actions":[{"uid":"410400101:201:1","speaker":"Urdr","text":"Then you will listen?\nYou have my thanks.","pose":20330104,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"那你会听吗？我对你表示感谢。"}]},{"id":202,"order":202,"actions":[{"uid":"410400101:202:1","speaker":"Urdr","text":"I wish for you to gather\na band of warriors as\nstrong as yourself.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我希望你能聚集一支和你一样强大的战士队伍。"}]},{"id":203,"order":203,"actions":[{"uid":"410400101:203:1","speaker":"Urdr","text":"Please work with them\nto save this realm.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"请与他们一起拯救这个王国。"}]}]};
